content.content:
1	/* ============================================
2	   共通リセット
3	   ============================================ */
4	html { scroll-behavior: smooth; }
5	@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { animation: none !important; } }
6	* { box-sizing: border-box; }
7	body { margin: 0; font-family: "Zen Kaku Gothic New", "Archivo", system-ui, sans-serif; -webkit-font-smoothing: antialiased; }
8	a { color: inherit; text-decoration: none; }
9	
10	/* ページテーマ（body class="page-xxx"） */
11	/* page-portfolio（404）・page-privacy はTOPページと同じネイビー×オレンジ配色。page-pianist・page-horror は現行デザインを維持（別途リニューアル予定のため変更しない） */
12	body.page-portfolio { background: #FFFFFF; color: #172E4A; }
13	body.page-privacy { background: #FFFFFF; color: #172E4A; }
14	body.page-pianist { background: #08080A; color: #F2EFE9; }
15	body:has(.pn-shell) {
16	  color: #F2EFE9;
17	  background: linear-gradient(180deg,rgba(8,8,10,0.4),rgba(8,8,10,0.65)), url("images/25253200_l.webp") center / cover no-repeat fixed, #08080A;
18	}
19	body:has(.top-shell) {
20	  background: #FFFFFF;
21	}
22	body.page-portfolio a:hover { color: #DC8541; }
23	body.page-privacy a:hover { color: #DC8541; }
24	body.page-pianist a:hover { color: #E4C97E; }
25	.pn-shell a:hover { color: #E4C97E; }
26	body.page-portfolio ::selection,
27	body.page-privacy ::selection { background: #F6D3B0; color: #172E4A; }
28	
29	body.page-horror { background: #07070A; color: #D6D2CB; }
30	body.page-horror a:hover { color: #9B2C22; }
31	
32	/* ============================================
33	   キーフレームアニメーション
34	   ============================================ */
35	@keyframes fadeup { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
36	@keyframes flick { 0%,100% { opacity: .85; } 47% { opacity: .85; } 48% { opacity: .35; } 52% { opacity: .9; } 70% { opacity: .6; } }
37	
38	/* ============================================
39	   共通ユーティリティ
40	   ============================================ */
41	.container { max-width: 1180px; margin: 0 auto; padding-inline: clamp(20px,5vw,64px); }
42	
43	.tag-row { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 10px; }
44	.tag { display: inline-flex; align-items: center; font-size: 12px; letter-spacing: 0.01em; color: #3E4A5C; border: 2.5px solid #172E4A; border-radius: 999px; padding: 8px 16px; background: #FFFFFF; white-space: nowrap; }
45	.tag--on-dark { color: #EAF0F6; border-color: rgba(234,240,246,0.32); background: rgba(255,255,255,0.06); }
46	
47	.btn-group { display: flex; flex-wrap: wrap; gap: 14px; align-items: center; }
48	.btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; font-weight: 700; font-size: 14px; letter-spacing: 0.09em; padding: 20px 34px; border-radius: 999px; border: 3px solid transparent; cursor: pointer; transition: background .25s ease, border-color .25s ease, color .25s ease, transform .15s ease; white-space: nowrap; }
49	.btn:hover { transform: translateY(-1px); }
50	.btn--primary { background: #DC8541; color: #FFFFFF; box-shadow: 5px 5px 0 #172E4A; }
51	.btn--primary:hover { background: #C06E2E; }
52	.btn--secondary { background: #FFFFFF; color: #172E4A; border-color: #172E4A; }
53	.btn--secondary:hover { background: #172E4A; color: #FFFFFF; }
54	.btn--on-dark { background: transparent; color: #FFFFFF; border-color: rgba(255,255,255,0.5); }
55	.btn--on-dark:hover { background: rgba(255,255,255,0.12); border-color: #FFFFFF; }
56	.btn--sm { padding: 13px clamp(14px,1.6vw,22px); font-size: 12px; font-weight: 600; box-shadow: 4px 4px 0 #172E4A; }
57	
58	/* ============================================
59	   shell（各ページ共通の外枠カード／pianist・horrorと共有のため触らない）
60	   ============================================ */
61	.shell {
62	  container-type: inline-size;
63	  max-width: 375px;
64	  margin: 0 auto;
65	  min-height: 100svh;
66	  position: relative;
67	  overflow-x: hidden;
68	  display: flex;
69	  flex-direction: column;
70	  background: #F5F8FC;
71	  box-shadow: 0 0 80px rgba(18,36,63,0.16);
72	}
73	.shell--muted { background: #F0F5FA; }
74	.shell--dark { background: #0B0B0C; box-shadow: 0 0 80px rgba(0,0,0,0.5); }
75	
76	.skip-link { position: absolute; left: -9999px; top: 0; background: #12243F; color: #F5F8FC; padding: 12px 18px; z-index: 200; }
77	.skip-link:focus { left: 12px; top: 12px; }
78	
79	/* ============================================
80	   page-header（下層ページの戻るリンクヘッダー／pianist・horrorと共有のため触らない）
81	   ============================================ */
82	.page-header { padding: 24px clamp(20px,6cqw,80px); display: flex; justify-content: space-between; align-items: center; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.16em; }
83	.page-header--dark { color: #8A8580; }
84	.page-header__back { display: inline-flex; align-items: center; gap: 10px; transition: gap .3s ease; }
85	.page-header__back:hover { gap: 18px; }
86	.page-header__label { color: #7B8DA6; }
87	
88	/* ============================================
89	   page-footer（下層ページ共通フッター／pianist・horrorと共有のため触らない）
90	   ============================================ */
91	.page-footer { padding: clamp(40px,5cqw,72px) clamp(20px,6cqw,80px); border-top: 1px solid #D3DEEB; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #7B8DA6; margin-top: auto; }
92	.page-footer--dark { border-top-color: #1E1D1D; color: #5A5652; }
93	
94	/* ============================================
95	   top-shell（TOPページのラッパー／固定フレームは使わずフル幅レスポンシブ／
96	   「手描きポップ」デザイン：太め枠線・オフセット影・回転バッジが基調）
97	   ============================================ */
98	.top-shell {
99	  min-height: 100svh;
100	  display: flex;
101	  flex-direction: column;
102	  overflow-x: hidden;
103	}
104	body:has(.top-shell) a:hover { color: #DC8541; }
105	body:has(.top-shell) ::selection { background: #F6D3B0; color: #172E4A; }
106	
107	@keyframes prupru {
108	  0% { transform: rotate(-2deg) translate(0,0); }
109	  12% { transform: rotate(2.4deg) translate(2px,-1px); }
110	  26% { transform: rotate(-3.2deg) translate(-2px,1px); }
111	  40% { transform: rotate(2.6deg) translate(2px,1px); }
112	  54% { transform: rotate(-2.4deg) translate(-1px,-1px); }
113	  68% { transform: rotate(1.6deg) translate(1px,0); }
114	  84% { transform: rotate(-2.4deg) translate(-1px,0); }
115	  100% { transform: rotate(-2deg) translate(0,0); }
116	}
117	
118	/* ============================================
119	   site-header（TOPページ固定ヘッダー／DCコンポーネントの状態クラス hero-nav / menu は名称を維持）
120	   ============================================ */
121	.hero-nav {
122	  position: sticky; top: 0; z-index: 96;
123	  display: flex; align-items: center; justify-content: space-between;
124	  gap: 20px;
125	  padding: 16px clamp(18px,5vw,56px);
126	  background: rgba(255,255,255,0.93);
127	  border-bottom: 4px solid #172E4A;
128	  backdrop-filter: blur(10px);
129	  -webkit-backdrop-filter: blur(10px);
130	}
131	.hero-nav__h1 { margin: 0; }
132	.hero-nav__logo { display: inline-flex; align-items: baseline; gap: 12px; line-height: 1; transition: opacity .2s ease; }
133	.hero-nav__logo-main { font-size: 18px; letter-spacing: 0.09em; color: #172E4A; font-weight: 500; transition: color .2s ease; }
134	.hero-nav__logo-sub { font-size: 9px; letter-spacing: 0.26em; color: #DC8541; transition: color .2s ease; }
135	.hero-nav__logo:hover .hero-nav__logo-main { color: #DC8541; }
136	.hero-nav__logo:hover .hero-nav__logo-sub { color: #172E4A; }
137	
138	.hero-nav__nav { display: none; }
139	.hero-nav__nav-list { list-style: none; margin: 0; padding: 0; display: flex; align-items: center; gap: clamp(14px,1.8vw,28px); font-size: 13.5px; color: #3E4A5C; }
140	.hero-nav__nav-list a { transition: color .2s ease; }
141	.hero-nav__nav-list a:hover { color: #DC8541; }
142	.hero-nav__actions { display: flex; align-items: center; gap: 10px; }
143	.hero-nav__cta--compact { display: none; }
144	
145	.hero-nav__toggle {
146	  width: 44px; height: 44px; display: flex; flex-direction: column;
147	  justify-content: center; align-items: center; gap: 6px; background: none; border: none;
148	  cursor: pointer; padding: 0; flex: none;
149	}
150	.hero-nav__bar {
151	  display: block; height: 2px; width: 22px; border-radius: 2px; background: #172E4A;
152	  transition: transform .35s cubic-bezier(.2,.7,.2,1), opacity .2s ease;
153	}
154	.hero-nav.is-open .hero-nav__bar--top { transform: translateY(4px) rotate(45deg); }
155	.hero-nav.is-open .hero-nav__bar--bottom { transform: translateY(-4px) rotate(-45deg); }
156	
157	@media (min-width: 880px) {
158	  .hero-nav__nav { display: block; }
159	  .hero-nav__toggle { display: none; }
160	  .hero-nav__cta--compact { display: none; }
161	}
162	@media (max-width: 879px) {
163	  .hero-nav__cta--full { display: none; }
164	  .hero-nav__cta--compact { display: inline-flex; }
165	}
166	
167	/* ============================================
168	   menu（ハンバーガーで開くフルスクリーンナビ／DCコンポーネントの状態クラス menu は名称を維持）
169	   ============================================ */
170	.menu {
171	  position: fixed; inset: 0; z-index: 95;
172	  background: #172E4A;
173	  display: flex; flex-direction: column;
174	  overflow-y: auto; -webkit-overflow-scrolling: touch;
175	  padding: 96px clamp(24px,7vw,56px) 48px;
176	  transition: opacity .4s ease, visibility .4s ease;
177	  opacity: 0; visibility: hidden; pointer-events: none;
178	}
179	.menu.is-open { opacity: 1; visibility: visible; pointer-events: auto; }
180	.menu__cta { margin-bottom: clamp(30px,6vw,48px); }
181	.menu__inner { display: grid; gap: clamp(28px,6vw,44px); width: 100%; max-width: 420px; }
182	.menu__group-title { font-size: 11px; letter-spacing: 0.24em; color: #9DB4CD; margin: 0 0 16px; }
183	.menu__nav-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; font-weight: 700; font-size: 20px; line-height: 1.25; color: #FFFFFF; }
184	.menu__social-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; font-size: 14px; color: #FFFFFF; }
185	.menu__social-link { display: inline-flex; align-items: center; gap: 12px; transition: transform .3s ease; }
186	.menu__social-link:hover { transform: translateX(8px); color: #DC8541; }
187	.menu__personal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 16px; }
188	.menu__personal-link { display: block; }
189	.menu__personal-link-title { display: block; font-size: 15px; color: #FFFFFF; transition: transform .3s ease; }
190	.menu__personal-link:hover .menu__personal-link-title { transform: translateX(8px); color: #DC8541; }
191	.menu__personal-link-desc { display: block; font-size: 12px; color: #9DB4CD; margin-top: 4px; }
192	.menu__credit { margin: 36px 0 0; font-size: 11px; letter-spacing: 0.16em; color: #6B85A6; }
193	
194	@media (min-width: 880px) {
195	  .menu { display: none; }
196	}
197	
198	/* ============================================
199	   section 基本パターン
200	   ============================================ */
201	.section { position: relative; padding-block: clamp(66px,9vw,120px); background: #FFFFFF; overflow: hidden; }
202	.section--alt { background: #FFF3E6; }
203	.section--dark { background: #172E4A; color: #EAF0F6; }
204	.section--tight { padding-block: clamp(40px,6vw,80px); }
205	
206	.section__head-row { display: flex; flex-wrap: wrap; align-items: center; gap: clamp(22px,4vw,48px); margin-bottom: clamp(34px,5vw,56px); }
207	.section__head { flex: 1 1 320px; min-width: 0; max-width: 760px; margin-bottom: clamp(32px,5vw,64px); }
208	.section__head-row .section__head { margin-bottom: 0; }
209	.section__head--center { margin-inline: auto; text-align: center; }
210	.section__deco { flex: 0 0 auto; width: clamp(120px,17vw,200px); aspect-ratio: 1/1; }
211	.section__deco img { width: 100%; height: 100%; object-fit: cover; display: block; border-radius: 32px; }
212	.section__eyebrow {
213	  display: inline-block; margin: 0 0 18px; font-weight: 700; font-size: 11px; line-height: 1;
214	  letter-spacing: 0.22em; color: #FFFFFF; background: #172E4A; padding: 9px 16px; border-radius: 999px;
215	  transform: rotate(-2deg);
216	}
217	.section--dark .section__eyebrow, .section--cta .section__eyebrow { background: #DC8541; color: #172E4A; }
218	.section__heading { margin: 0; font-weight: 900; font-size: clamp(26px,3.6vw,44px); line-height: 1.42; letter-spacing: -0.01em; color: #172E4A; }
219	.section--dark .section__heading, .section--cta .section__heading { color: #FFFFFF; }
220	.section__lead { margin: 18px 0 0; font-size: 15px; line-height: 2; color: #56637A; }
221	.section--dark .section__lead { color: #C3D0E0; }
222	.section__lead--note { font-size: 13px; opacity: .82; }
223	.section__pretitle { margin: 0 0 10px; font-weight: 900; font-size: clamp(18px,2.4vw,24px); line-height: 1.5; color: #DC8541; }
224	
225	/* ============================================
226	   hero
227	   ============================================ */
228	.hero { padding-top: clamp(48px,8vw,92px); padding-bottom: clamp(60px,9vw,104px); background: linear-gradient(180deg,#FFFFFF 0%,#FFF3E6 100%); overflow: hidden; }
229	.hero__inner { display: grid; gap: clamp(40px,6vw,64px); align-items: center; }
230	.hero__audience { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 0 0 16px; padding: 8px 16px; border: 2.5px solid #DC8541; border-radius: 999px; background: #FFFFFF; }
231	.hero__audience-en { font-size: 10px; letter-spacing: 0.18em; color: #DC8541; font-weight: 700; }
232	.hero__audience-ja { font-size: 12.5px; font-weight: 700; color: #172E4A; }
233	.hero__eyebrow { display: flex; align-items: center; gap: 14px; font-size: 11.5px; letter-spacing: 0.22em; color: #8A7B6C; margin: 0 0 clamp(20px,3vw,26px); }
234	.hero__eyebrow-line { width: 7px; height: 7px; border-radius: 50%; background: #DC8541; }
235	.hero__heading { margin: 0; font-weight: 900; font-size: clamp(26px,4.2vw,52px); line-height: 1.45; letter-spacing: -0.01em; color: #172E4A; }
236	.hero__line { display: block; }
237	.hero__highlight { position: relative; display: inline-block; color: #172E4A; }
238	.hero__highlight::after { content: ""; position: absolute; left: 0; right: 0; bottom: 6px; height: 12px; background: rgba(220,133,65,0.24); border-radius: 6px; z-index: -1; }
239	.hero__lead { margin: clamp(24px,3vw,32px) 0 0; font-size: 15px; line-height: 2.05; color: #56637A; max-width: 46ch; }
240	.hero__tags { margin-top: clamp(22px,3vw,30px); }
241	.hero__actions { margin-top: clamp(28px,4vw,38px); }
242	
243	.hero__visual { position: relative; display: flex; justify-content: center; }
244	.hero__photo {
245	  position: relative; width: 100%; max-width: 320px; margin: 0 auto; aspect-ratio: 4/5;
246	  border: 2.5px solid #172E4A; border-radius: 170px 170px 26px 26px;
247	  background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px);
248	  display: flex; align-items: center; justify-content: center; overflow: hidden;
249	}
250	.hero__photo-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #8A93A3; background: #FFFFFF; padding: 6px 14px; border: 1px solid #E3E6EB; border-radius: 999px; }
251	
252	@media (min-width: 860px) {
253	  .hero__inner { grid-template-columns: minmax(0,1fr) 320px; }
254	  .hero__visual { order: 2; }
255	}
256	
257	/* ============================================
258	   tile-grid（PROBLEMS / TEAM / WORK STYLE 共通／太枠＋オフセット影のポップカード）
259	   ============================================ */
260	.tile-grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2,1fr); gap: 16px; }
261	.tile { display: flex; flex-direction: column; align-items: center; gap: 18px; text-align: center; background: #FFFFFF; border: 3px solid #172E4A; border-radius: 24px; padding: clamp(24px,3vw,32px); box-shadow: 6px 6px 0 #172E4A; }
262	.tile__icon img { width: auto; height: clamp(60px,8vw,92px); object-fit: contain; display: block; }
263	.tile__text { margin: 0; font-size: 14.5px; line-height: 1.85; color: #172E4A; font-weight: 500; }
264	.tile__label { font-size: 14px; font-weight: 700; line-height: 1.6; color: #172E4A; }
265	
266	.tile-grid--dot .tile--row { flex-direction: row; align-items: center; justify-content: flex-start; gap: 14px; text-align: left; box-shadow: none; padding: 20px 22px; }
267	.tile__dot { flex: none; width: 28px; height: 28px; border-radius: 50%; background: rgba(220,133,65,0.14); display: flex; align-items: center; justify-content: center; }
268	.tile__dot::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: #DC8541; }
269	
270	@media (min-width: 640px) {
271	  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
272	}
273	@media (min-width: 880px) {
274	  .tile-grid--6 { grid-template-columns: repeat(6,1fr); }
275	  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
276	}
277	
278	/* ============================================
279	   scope-highlight（SCOPE／常時表示の主要3項目）
280	   ============================================ */
281	.scope-highlight { list-style: none; margin: 0 0 clamp(28px,4vw,40px); padding: 0; display: grid; gap: 14px; }
282	.scope-highlight__item { background: #FFFFFF; border: 3px solid #172E4A; border-left-width: 10px; border-left-color: #DC8541; border-radius: 18px; padding: 22px 24px; }
283	.scope-highlight__title { margin: 0; font-weight: 700; font-size: 16px; color: #172E4A; }
284	.scope-highlight__text { margin: 10px 0 0; font-size: 13.5px; line-height: 1.9; color: #56637A; }
285	
286	@media (min-width: 880px) {
287	  .scope-highlight { grid-template-columns: repeat(3,1fr); }
288	}
289	
290	/* ============================================
291	   team-scope（TEAM／Web Directionを主役にした情報階層）
292	   ============================================ */
293	.team-scope { display: grid; gap: 20px; }
294	.team-scope__primary { display: flex; flex-direction: column; align-items: center; gap: 14px; text-align: center; background: #172E4A; color: #FFFFFF; border: 3px solid #172E4A; border-radius: 26px; padding: clamp(28px,4vw,40px); box-shadow: 8px 8px 0 #A85A1E; }
295	.team-scope__primary .tile__icon { display: inline-flex; align-items: center; justify-content: center; background: #FFFFFF; border-radius: 50%; padding: clamp(14px,2vw,20px); }
296	.team-scope__primary .tile__icon img { width: auto; height: clamp(56px,7vw,80px); object-fit: contain; display: block; }
297	.team-scope__primary-label { margin: 0; font-weight: 900; font-size: clamp(20px,2.6vw,26px); color: #FFFFFF; }
298	.team-scope__primary-tag { margin: 0; font-size: 11px; letter-spacing: 0.16em; color: #E0B98F; }
299	.team-scope__secondary { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2,1fr); gap: 12px; }
300	.team-scope__secondary li { display: flex; flex-direction: column; align-items: center; gap: 10px; text-align: center; background: #FFFFFF; border: 2px solid #D7DEE8; border-radius: 18px; padding: clamp(16px,2vw,22px); }
301	.team-scope__secondary .tile__icon img { width: auto; height: clamp(40px,5vw,56px); object-fit: contain; display: block; opacity: .85; }
302	.team-scope__secondary .tile__label { font-size: 12.5px; font-weight: 600; color: #3E4A5C; }
303	
304	@media (min-width: 640px) {
305	  .team-scope__secondary { grid-template-columns: repeat(5,1fr); }
306	}
307	
308	/* ============================================
309	   timeline（SCOPE / PROFILE経歴 共通／カード積み上げ型のチェックリスト）
310	   ============================================ */
311	.timeline { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
312	.timeline__item { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 16px; padding: 16px 20px; border: 3px dashed #172E4A; border-radius: 18px; background: #FFFFFF; }
313	.timeline__no { font-size: 12px; letter-spacing: 0.14em; color: #A7AFBC; flex: none; width: 22px; }
314	.timeline__label { flex: 1; font-size: 15px; font-weight: 500; color: #172E4A; min-width: 120px; }
315	.timeline__badge { flex: none; font-size: 11px; letter-spacing: 0.04em; color: #8A93A3; }
316	.timeline__item--covered { border: 3px solid #172E4A; border-left-width: 10px; border-left-color: #DC8541; }
317	.timeline__item--covered .timeline__no { color: #DC8541; }
318	.timeline__item--covered .timeline__badge { color: #C06E2E; font-weight: 600; background: rgba(220,133,65,0.12); border-radius: 999px; padding: 6px 12px; }
