553	.horror-gate__enter:hover { background: #9B2C22; border-color: #9B2C22; letter-spacing: 0.42em; }
554	.horror-gate__back { margin-top: 28px; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #5A5652; }
555	
556	.horror-hero { padding: clamp(60px,10cqw,150px) clamp(20px,6cqw,80px) clamp(50px,7cqw,110px); border-bottom: 1px solid #1E1D1D; }
557	.horror-hero__title { margin: 0; font-family: Archivo, sans-serif; font-weight: 400; font-size: clamp(52px,14cqw,190px); line-height: 0.9; letter-spacing: -0.03em; color: #EDE9E3; }
558	.horror-hero__desc { margin: clamp(28px,4cqw,52px) 0 0; font-size: 15px; line-height: 2.2; color: #9A948C; max-width: 44ch; }
559	
560	.horror-archive { padding: clamp(50px,7cqw,110px) clamp(20px,6cqw,80px); }
561	.horror-archive__eyebrow { font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #5A5652; margin: 0 0 clamp(28px,4cqw,48px); }
562	.horror-archive__grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit,minmax(260px,1fr)); gap: clamp(24px,3cqw,44px); }
563	.horror-archive__thumb { aspect-ratio: 16/10; background-image: repeating-linear-gradient(135deg,#141414 0 10px,#101010 10px 20px); border: 1px solid #1E1D1D; display: flex; align-items: center; justify-content: center; transition: border-color .4s ease; }
564	.horror-archive__thumb:hover { border-color: #9B2C22; }
565	.horror-archive__thumb-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #5A5652; }
566	.horror-archive__no { margin: 16px 0 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #5A5652; }
567	.horror-archive__title { margin: 8px 0 0; font-size: 15px; color: #C7C2BB; }
568	
569	.dream-experience { position: relative; overflow: hidden; background: #050506; border-top: 1px solid #1E1D1D; border-bottom: 1px solid #1E1D1D; }
570	.dream-experience__noise { position: absolute; inset: 0; opacity: .12; pointer-events: none; background-image: repeating-linear-gradient(0deg,transparent 0 3px,rgba(255,255,255,.08) 4px,transparent 5px); mix-blend-mode: screen; }
571	.dream-experience__inner { position: relative; padding: clamp(70px,10cqw,140px) clamp(20px,6cqw,80px) clamp(80px,11cqw,160px); }
572	.dream-experience__eyebrow { margin: 0; color: #9B2C22; font: 11px Archivo, sans-serif; letter-spacing: .25em; }
573	.dream-experience__title { margin: 22px 0 0; color: #EDE9E3; font: 400 clamp(42px,12cqw,160px)/.9 Archivo, sans-serif; letter-spacing: -.04em; }
574	.dream-experience__lead { margin: 28px 0 0; color: #8A8580; font-size: 13px; line-height: 2; }
575	.dream-stage { position: relative; min-height: 300px; margin: 54px 0 0; border: 1px solid #292627; background: radial-gradient(circle at 50% 52%,#1b1818 0,#0b0a0b 38%,#050506 76%); display: flex; align-items: center; justify-content: center; overflow: hidden; }
576	.dream-stage__sky { position: absolute; inset: 0; opacity: .35; background: repeating-linear-gradient(90deg,transparent 0 46px,rgba(155,44,34,.12) 47px,transparent 48px); animation: dreamDrift 8s linear infinite; }
577	.dream-stage__ear { position: relative; width: 118px; height: 174px; border: 3px solid #B9B0A9; border-radius: 54% 46% 48% 52% / 44% 46% 54% 56%; transform: rotate(-17deg); opacity: .85; box-shadow: inset -10px -5px 0 rgba(155,44,34,.12); }
578	.dream-stage__ear::before { content: ""; position: absolute; width: 48px; height: 82px; left: 31px; top: 42px; border: 3px solid #8A8580; border-radius: 50%; }

