python3 -c "
import re
html = open('index.html').read()
# crude tag balance check for div only within main content
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag in ('br','img','input','hr','meta','link'):
            return
        self.stack.append(tag)
    def handle_endtag(self, tag):
        if not self.stack:
            self.errors.append(f'extra close {tag}')
            return
        if self.stack[-1] == tag:
            self.stack.pop()
        else:
            self.errors.append(f'mismatch: expected close {self.stack[-1]}, got {tag}')
            # try to recover by popping until match found
            if tag in self.stack:
                while self.stack and self.stack[-1] != tag:
                    self.stack.pop()
                if self.stack:
                    self.stack.pop()
p = P()
p.feed(html)
print('remaining open tags:', p.stack[-20:])
print('errors count:', len(p.errors))
for e in p.errors[:30]:
    print(e)
"

