input.text:
const btn = document.querySelector('.hero-nav__cta--full');
const matched = [];
for (const sheet of document.styleSheets) {
  let rules;
  try { rules = sheet.cssRules; } catch(e) { continue; }
  for (const rule of rules) {
    if (!rule.selectorText) continue;
    try {
      if (btn.matches(rule.selectorText) && /box-shadow/.test(rule.style.cssText)) {
        matched.push(rule.selectorText + ' => ' + rule.style.boxShadow);
      }
    } catch(e) {}
  }
}
JSON.stringify(matched)

