from html.parser import HTMLParser
html = open('index.html').read()
class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag in ('br','img','input','hr','meta','link'):
            return
        self.stack.append(tag)
    def handle_endtag(self, tag):
        if not self.stack:
            self.errors.append(f'extra close {tag}')
            return
        if self.stack[-1] == tag:
            self.stack.pop()
        else:
            self.errors.append(f'mismatch: expected close {self.stack[-1]}, got {tag}')
            if tag in self.stack:
                while self.stack and self.stack[-1] != tag:
                    self.stack.pop()
                if self.stack:
                    self.stack.pop()
p = P()
p.feed(html)
print('remaining open tags:', p.stack[-20:])
print('errors:', p.errors[:20])
"

